// Home Health Aide Practice Test 4. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–3.
import {q, mix} from './q.js';
const BAL='Balduzzi, Homemaker Home Health Aide', HART='Leahy, Fuzy & Grafe, Providing Home Care';
const RESP='Responsibilities and Legal/Ethical Issues', COMM='Effective Communication', INF='Infection Control and Safety', BODY='Body Systems and Common Disorders', SPEC='Caring for Special Populations', SKILL='Basic Healthcare Skills';

export default {
 id:'home-health-aide-4',
 event:'Home Health Aide',
 title:'Practice Test 4',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Balduzzi’s Homemaker Home Health Aide and Leahy, Fuzy & Grafe’s Providing Home Care',
 plan:[{area:RESP,weight:10},{area:COMM,weight:6},{area:INF,weight:10},{area:BODY,weight:40},{area:SPEC,weight:24},{area:SKILL,weight:10}],
 questions:mix([
  q(RESP,'A client refuses a bath the aide planned to give. What should the aide do?','Respect the choice and report it',['Give the bath anyway to stay on time','Tell the client the nurse insists','Skip it and say nothing to anyone'],'A','Clients have the right to refuse care, and the nurse needs to know about refusals.',HART),
  q(RESP,'Which action by an aide is negligence?','Forgetting to lock the bed wheels',['Asking the nurse about a task','Reporting a change in the client','Following the written care plan'],'B','Negligence is failing to give the care a reasonable aide would give, causing harm.',HART),
  q(RESP,'What is an advance directive?','Written wishes about future care',['A bill for home health visits','A list of the aide’s duties','A schedule of daily meals'],'C','Living wills and health care powers of attorney are types of advance directives.',HART),
  q(RESP,'Which situation must an aide report as possible abuse?','A client with burns no one can explain',['A client who naps after lunch','A client who prefers tea to coffee','A client with a healed old scar'],'D','Aides are mandated reporters and must report suspected abuse to their supervisor.',HART),
  q(RESP,'Which statement about client care notes is correct?','They are legal records',['They can be written in pencil','They may include guesses','They can be shared online'],'A','Notes must be accurate, factual, signed and kept confidential.',HART),
  q(COMM,'What is the best way to show a client you are listening?','Make eye contact and nod',['Look at your phone often','Interrupt with your story','Finish their sentences'],'B','Active listening shows respect and encourages the client to share concerns.',HART),
  q(COMM,'A client speaks a different language from the aide. What should the aide do?','Ask the agency for an interpreter',['Use a young child to interpret','Avoid speaking to the client','Speak louder in English only'],'C','Trained interpreters protect accuracy and privacy; children should not interpret.',HART),
  q(COMM,'Which statement is a subjective observation?','“My stomach hurts,” the client says',['The client vomited twice today','The client’s pulse is 110','The client has a rash on her arm'],'D','Subjective observations are what the client tells you and cannot be measured.',HART),
  q(INF,'Which type of precautions are used with every client?','Standard precautions',['Airborne precautions','Droplet precautions','Contact precautions'],'A','Standard precautions treat all blood and body fluids as possibly infectious.',BAL),
  q(INF,'Which item should an aide put on first when entering a client’s room with contact precautions?','Gown',['Gloves','Booties','Hair net'],'B','The gown goes on first so gloves can be pulled over the gown cuffs.',BAL),
  q(INF,'What is the safest way to put out a small grease fire on the stove?','Cover the pan with a lid',['Pour water on the flames','Carry the pan outside','Fan the flames with a towel'],'C','Water spreads burning grease, so smother it with a lid and turn off the heat.',BAL),
  q(INF,'What does the PASS acronym stand for when using a fire extinguisher?','Pull, Aim, Squeeze, Sweep',['Push, Alert, Spray, Stop','Pull, Alarm, Shut, Stay','Point, Aim, Shoot, Spin'],'D','PASS reminds users to aim at the base of the fire and sweep from side to side.',BAL),
  q(INF,'Which practice reduces the spread of germs in a client’s kitchen?','Separate cutting boards for raw meat',['Use one sponge for every task','Leave food out to cool all night','Wash raw chicken in the sink'],'A','Separating raw meat from other foods prevents cross-contamination.',BAL),
  q(BODY,'Which condition causes high pressure inside the eye and can lead to blindness?','Glaucoma',['Cataracts','Pink eye','Dry eye'],'B','Glaucoma often has no early symptoms, so regular eye exams are needed.',HART),
  q(BODY,'Which sign is common in a client with emphysema?','A barrel-shaped chest',['A very slow heart rate','Yellowing of the skin','Swollen, red joints'],'C','Air trapped in damaged lungs makes the chest round and enlarged.',HART),
  q(BODY,'Which disorder causes the body to attack the protective coating of nerves?','Multiple sclerosis',['Osteoarthritis','Kidney stones','Hypertension'],'D','Symptoms such as weakness, numbness and vision changes can come and go.',HART),
  q(BODY,'What is a normal adult blood pressure?','Below 120/80 mmHg',['Above 160/100 mmHg','Exactly 140/95 mmHg','Above 180/110 mmHg'],'A','Blood pressure at or above 130/80 is considered high by current guidelines.',HART),
  q(BODY,'Which body system includes the brain and spinal cord?','Nervous system',['Digestive system','Respiratory system','Lymphatic system'],'B','The brain, spinal cord and nerves control movement, thought and sensation.',HART),
  q(BODY,'Which digestive disorder involves inflamed pouches in the colon?','Diverticulitis',['Gallstones','Heartburn','Hemorrhoids'],'C','Symptoms include lower left belly pain, fever and changes in bowel habits.',HART),
  q(BODY,'Which sign may show that a client’s hearing aid needs a new battery?','Whistling or no sound',['Better hearing than usual','A warm, dry ear canal','Clear sound in noisy rooms'],'D','Aides should check that hearing aids are on, clean and working each visit.',HART),
  q(BODY,'Which hormone does the pancreas make to lower blood sugar?','Insulin',['Thyroxine','Cortisol','Adrenaline'],'A','Insulin moves sugar into cells; without enough insulin, sugar builds up in the blood.',HART),
  q(BODY,'Which finding should be reported for a client with an ostomy?','A dark purple stoma',['A moist, pink stoma','A bag that is half full','Normal stool in the pouch'],'B','A healthy stoma is pink and moist; a dark color may mean poor blood flow.',HART),
  q(BODY,'Which symptom is typical of a client with anemia?','Tiredness and pale skin',['Very high energy levels','Flushed, red skin color','Fast weight gain only'],'C','Anemia means fewer red blood cells to carry oxygen to the body.',HART),
  q(BODY,'Which condition causes the heart to pump too weakly to meet the body’s needs?','Heart failure',['Varicose veins','Hemorrhoids','Raynaud’s'],'D','Swelling, shortness of breath and weight gain are common signs to report.',HART),
  q(BODY,'What is the main purpose of the respiratory system?','Exchange oxygen and carbon dioxide',['Break down food into nutrients','Filter waste out of the blood','Make hormones for body growth'],'A','Gas exchange happens in tiny air sacs in the lungs called alveoli.',HART),
  q(BODY,'Which skin problem is caused by moisture and friction in skin folds?','Skin breakdown and rashes',['Better skin healing','Thicker, stronger skin','Fewer bacteria on skin'],'B','Keeping skin clean and dry helps prevent rashes and infections.',HART),
  q(BODY,'Which finding is a sign of shingles?','A painful rash on one side',['A painless rash on both legs','Small bumps on the scalp only','Dry skin across the whole body'],'C','Shingles is caused by the chickenpox virus becoming active again.',HART),
  q(BODY,'Which condition causes loss of central vision in older adults?','Macular degeneration',['Pink eye infection','Seasonal allergies','Nearsightedness'],'D','Macular degeneration blurs central vision, so clients may need bright lighting and large print.',HART),
  q(BODY,'Which disease causes muscle weakness that worsens with activity and improves with rest?','Myasthenia gravis',['Osteoporosis','Chronic gout','Diverticulosis'],'A','Clients should plan important activities when they have the most energy.',HART),
  q(BODY,'A client with a urinary tract infection should be encouraged to:','Drink plenty of fluids',['Limit all fluid intake','Hold urine for hours','Avoid all fruit juices'],'B','Drinking plenty of fluids helps flush bacteria out of the urinary tract.',HART),
  q(BODY,'Which sign could mean a client has a fracture after a fall?','Pain, swelling and deformity',['Normal walking without pain','A warm cup of tea in hand','Slightly dry lips'],'C','Do not move the client; keep them still and warm, call for help and report the fall.',HART),
  q(BODY,'Which gland is called the “master gland” because it controls other glands?','Pituitary gland',['Thyroid gland','Adrenal gland','Salivary gland'],'D','The pituitary releases hormones that control growth, thyroid and adrenal function.',HART),
  q(BODY,'Which symptom suggests a client may be having a heart attack?','Chest pressure spreading to the arm',['Mild itching on both arms','A runny nose and sneezing','Ringing in both of the ears'],'A','Call 911 right away; women may have nausea, tiredness or back pain instead.',HART),
  q(SPEC,'How should an aide approach a client with dementia?','From the front, calmly',['From behind, quickly','From the side, loudly','Without any greeting'],'B','Approaching from the front avoids startling the client and causing fear.',HART),
  q(SPEC,'A client with dementia repeats the same question many times. What should the aide do?','Answer calmly each time',['Remind her she already asked','Ignore the question','Raise your voice to stop it'],'C','Memory loss makes the question feel new to the client each time.',HART),
  q(SPEC,'Which approach helps a client with a visual impairment eat?','Describe food using a clock face',['Feed the client without speaking','Move food around the plate often','Serve all foods mixed together'],'D','Saying “meat at 3 o’clock” helps the client find foods independently.',HART),
  q(SPEC,'Which stage of grief involves saying “This can’t be happening”?','Denial',['Anger','Bargaining','Acceptance'],'A','Kübler-Ross described denial, anger, bargaining, depression and acceptance.',HART),
  q(SPEC,'What is the purpose of respite care for family caregivers?','A short break from caregiving',['Permanent nursing home care','Daily surgery for the client','Hospital emergency services'],'B','Respite care gives family caregivers time off and helps prevent burnout and stress.',HART),
  q(SPEC,'Which item should be removed from a home with a toddler for safety?','Small objects that fit in the mouth',['Soft stuffed animals that are large','Large picture books with no parts','Sturdy wooden building blocks'],'C','Toddlers explore with their mouths and can choke on small objects.',HART),
  q(SPEC,'Which approach helps a client with a new amputation?','Report any phantom pain',['Tell them phantom pain is imaginary','Do all tasks for them every day','Avoid talking about the amputation'],'D','Phantom pain is real and should be reported so it can be treated.',HART),
  q(SPEC,'Which sign suggests a client may be thinking about suicide?','Giving away personal items',['Planning a family dinner','Asking for a new book','Talking about next summer'],'A','Report warning signs right away and stay with the client if they are in danger.',HART),
  q(SPEC,'A client with obsessive-compulsive disorder washes her hands many times. What should the aide do?','Be patient and report the behavior',['Lock the sink so it cannot be used','Laugh to make the client feel better','Scold the client for wasting time'],'B','Compulsions ease anxiety for the client; treatment is planned by the care team.',HART),
  q(SPEC,'Which practice supports a client’s cultural or religious beliefs?','Respect dietary customs',['Serve foods they avoid','Ask them to change beliefs','Mock their practices'],'C','Food choices may be tied to religion, such as avoiding pork or meat on certain days.',HART),
  q(SPEC,'Which approach helps a client with a spinal cord injury prevent pressure injuries?','Reposition at least every 2 hours',['Keep the client in one position','Rub reddened areas very hard','Leave wet linens until later'],'D','Clients who cannot feel pressure need regular turning and skin checks.',HART),
  q(SPEC,'Which finding in a newborn should be reported right away?','Yellow skin within the first day',['Sleeping most of the day','Feeding every 2 to 3 hours','Wetting 6 diapers a day'],'A','Jaundice in the first 24 hours is not normal and may be serious.',HART),
  q(SKILL,'What is a normal adult respiratory rate at rest?','12 to 20 breaths per minute',['4 to 8 breaths per minute','25 to 35 breaths per minute','40 to 50 breaths per minute'],'B','Count breaths without telling the client, since people change breathing when watched.',BAL),
  q(SKILL,'Where should a client’s call bell or phone be placed?','Within easy reach',['Across the room','In another room','In a high cabinet'],'C','Clients must be able to get help quickly if they fall or feel sick.',BAL),
  q(SKILL,'What is the correct way to help a client with range-of-motion exercises?','Move joints gently to the point of resistance',['Force joints past the point of pain','Move joints as fast as possible','Skip joints that are stiff or sore'],'D','Never force a joint; stop if the client reports pain, and report it to the nurse.',BAL),
  q(SKILL,'Which temperature site is most accurate for adults if allowed?','Rectal',['Axillary','Wrist','Forehead touch'],'A','Rectal temperatures are not used for clients with heart problems or after rectal surgery.',BAL),
  q(SKILL,'How should a client with weakness on the left side get out of bed?','Lead with the strong right side',['Lead with the weak left side','Roll out without any help','Jump off the side quickly'],'B','Moving toward the strong side gives the client better balance and control.',BAL)
 ],8020)
};
